package com.example

/**
 * Grade 10 Mathematics Syllabus Question Bank for Live Exam Hall.
 * Covers Terms 1, 2, and 3 with 60 distinct syllabus topic slots per term.
 * Permutes slots with coprime 7 so each paper presents all 60 syllabus points in unique sequence,
 * and varies mathematical coefficients across papers 1 to 30.
 */
object MathGrade10QuestionBank {

  fun getQuestion(term: Int, paperIdx: Int, qNum: Int): MockExamQuestion {
    val cleanPaper = if (paperIdx in 1..30) paperIdx else 1
    val cleanQ = if (qNum in 1..60) qNum else 1
    val effectiveSlot = ((cleanQ - 1 + (cleanPaper - 1) * 7) % 60) + 1
    return when (term) {
      1 -> getTerm1Question(cleanPaper, cleanQ, effectiveSlot)
      2 -> getTerm2Question(cleanPaper, cleanQ, effectiveSlot)
      else -> getTerm3Question(cleanPaper, cleanQ, effectiveSlot)
    }
  }

  // ==========================================================================
  // GRADE 10 - TERM 1 (Slots 1 to 60)
  // ==========================================================================
  private fun getTerm1Question(paperIdx: Int, qNum: Int, slot: Int): MockExamQuestion {
    val v = paperIdx - 1
    val (topic, quad) = when (slot) {
      in 1..7 -> "තල රූපවල පරිමිතිය" to run {
        val perimList = listOf(
          Quad("දිග ${10 + v} cm සහ පළල ${6 + (v % 4)} cm වන සෘජුකෝණාස්‍රාකාර රූපයක මුළු පරිමිතිය කොපමණද?", listOf("${2 * ((10 + v) + (6 + (v % 4)))} cm", "${((10 + v) + (6 + (v % 4)))} cm", "${(10 + v) * (6 + (v % 4))} cm", "${2 * (10 + v)} cm"), 1, "සෘජුකෝණාස්‍රයක පරිමිතිය = 2(දිග + පළල) = 2(${10 + v} + ${6 + (v % 4)}) = ${2 * ((10 + v) + (6 + (v % 4)))} cm වේ."),
          Quad("අරය ${7 * (1 + (v % 3))} cm වූ අර්ධ වෘත්තාකාර චාපයක දිග (Arc length) ගණනය කරන්න. (π = 22/7)", listOf("${22 * (1 + (v % 3))} cm", "${44 * (1 + (v % 3))} cm", "${14 * (1 + (v % 3))} cm", "${36 * (1 + (v % 3))} cm"), 1, "අර්ධ වෘත්තයක චාප දිග = πr = (22/7) × ${7 * (1 + (v % 3))} = ${22 * (1 + (v % 3))} cm වේ."),
          Quad("අරය ${7 * (1 + (v % 3))} cm වන අර්ධ වෘත්තාකාර තහඩුවක සම්පූර්ණ වටප්‍රමාණය (පරිමිතිය) කොපමණද? (π = 22/7)", listOf("${22 * (1 + (v % 3)) + 2 * 7 * (1 + (v % 3))} cm", "${22 * (1 + (v % 3))} cm", "${44 * (1 + (v % 3))} cm", "${14 * (1 + (v % 3))} cm"), 1, "අර්ධ වෘත්ත පරිමිතිය = πr + 2r = ${22 * (1 + (v % 3))} + ${14 * (1 + (v % 3))} = ${36 * (1 + (v % 3))} cm වේ."),
          Quad("කේන්ද්‍රික කෝණය 60° ක් සහ අරය ${21 + (v % 3) * 7} cm වූ කේන්ද්‍රික ඛණ්ඩයක චාපයේ දිග සොයන්න.", listOf("${(2 * 22 * (21 + (v % 3) * 7)) / (7 * 6)} cm", "44 cm", "22 cm", "11 cm"), 1, "චාප දිග = (θ/360°) × 2πr = (60/360) × 2 × (22/7) × ${21 + (v % 3) * 7} cm වේ."),
          Quad("එක් පාදයක දිග ${5 + (v % 5)} cm වන සමපාද ත්‍රිකෝණයක වටප්‍රමාණය කුමක්ද?", listOf("${3 * (5 + (v % 5))} cm", "${2 * (5 + (v % 5))} cm", "${4 * (5 + (v % 5))} cm", "${(5 + (v % 5)) * (5 + (v % 5))} cm"), 1, "සමපාද ත්‍රිකෝණයක පරිමිතිය = 3 × පාදයක දිග = 3 × ${5 + (v % 5)} = ${3 * (5 + (v % 5))} cm වේ."),
          Quad("පැත්තක දිග ${8 + (v % 6)} cm වූ සමචතුරස්‍රාකාර තහඩුවක මුළු පරිමිතිය කොපමණද?", listOf("${4 * (8 + (v % 6))} cm", "${2 * (8 + (v % 6))} cm", "${(8 + (v % 6)) * (8 + (v % 6))} cm", "32 cm"), 1, "සමචතුරස්‍රයක පරිමිතිය = 4 × පාදය = 4 × ${8 + (v % 6)} = ${4 * (8 + (v % 6))} cm වේ."),
          Quad("අරය ${14 + (v % 2) * 7} cm වූ කේන්ද්‍රික කෝණය 90° වන කේන්ද්‍රික ඛණ්ඩයේ චාප දිග සොයන්න.", listOf("${(2 * 22 * (14 + (v % 2) * 7)) / (7 * 4)} cm", "44 cm", "11 cm", "28 cm"), 1, "වෘත්ත පාදයක චාප දිග = (1/4) × 2πr = (1/4) × 2 × (22/7) × ${14 + (v % 2) * 7} cm වේ.")
        )
        perimList[(slot - 1 + v).mod(perimList.size)]
      }
      in 8..14 -> "තල රූපවල වර්ගඵලය" to run {
        val areaList = listOf(
          Quad("පදනම (ආධාරකය) ${12 + (v % 4) * 2} cm සහ ලම්භ උස ${8 + (v % 3)} cm වූ ත්‍රිකෝණයක වර්ගඵලය ගණනය කරන්න.", listOf("${((12 + (v % 4) * 2) * (8 + (v % 3))) / 2} cm²", "${(12 + (v % 4) * 2) * (8 + (v % 3))} cm²", "48 cm²", "96 cm²"), 1, "ත්‍රිකෝණ වර්ගඵලය = 1/2 × ආධාරකය × ලම්භ උස = 1/2 × ${12 + (v % 4) * 2} × ${8 + (v % 3)} = ${((12 + (v % 4) * 2) * (8 + (v % 3))) / 2} cm²."),
          Quad("සමාන්තර පාදවල දිග ${10 + v} cm සහ ${6 + v} cm වන, ලම්භ දුර 4 cm වූ ත්‍රපීසියමක වර්ගඵලය කුමක්ද?", listOf("${((10 + v + 6 + v) * 4) / 2} cm²", "${(10 + v + 6 + v) * 4} cm²", "32 cm²", "64 cm²"), 1, "ත්‍රපීසියමේ වර්ගඵලය = 1/2 × (සමාන්තර පාදවල එකතුව) × ලම්භ දුර = 1/2 × (${10 + v} + ${6 + v}) × 4 = ${((10 + v + 6 + v) * 4) / 2} cm²."),
          Quad("ආධාරකයේ දිග ${15 + (v % 5)} cm සහ ලම්භ උස ${6 + (v % 3)} cm වන සමාන්තරාස්‍රාකාර රූපයක වර්ගඵලය සොයන්න.", listOf("${(15 + (v % 5)) * (6 + (v % 3))} cm²", "${((15 + (v % 5)) * (6 + (v % 3))) / 2} cm²", "90 cm²", "100 cm²"), 1, "සමාන්තරාස්‍රයක වර්ගඵලය = ආධාරකය × ලම්භ උස = ${15 + (v % 5)} × ${6 + (v % 3)} = ${(15 + (v % 5)) * (6 + (v % 3))} cm²."),
          Quad("අරය ${7 * (1 + (v % 2))} cm වන වෘත්තයක වර්ගඵලය කොපමණද? (π = 22/7)", listOf("${(22 * 7 * (1 + (v % 2)) * 7 * (1 + (v % 2))) / 7} cm²", "154 cm²", "44 cm²", "88 cm²"), 1, "වෘත්ත වර්ගඵලය = πr² = (22/7) × ${7 * (1 + (v % 2))}² = ${(22 * 7 * (1 + (v % 2)) * 7 * (1 + (v % 2))) / 7} cm²."),
          Quad("කේන්ද්‍රික කෝණය 90° ක් සහ අරය ${14 + (v % 2) * 7} cm වූ වෘත්ත පාදයක (කේන්ද්‍රික ඛණ්ඩයක) වර්ගඵලය සොයන්න.", listOf("${(22 * (14 + (v % 2) * 7) * (14 + (v % 2) * 7)) / (7 * 4)} cm²", "154 cm²", "77 cm²", "308 cm²"), 1, "වර්ගඵලය = (90/360) × πr² = 1/4 × (22/7) × r² වේ."),
          Quad("විකර්ණවල දිග පිළිවෙලින් ${10 + (v % 4) * 2} cm සහ ${8 + (v % 3) * 2} cm වූ රොම්බසයක වර්ගඵලය කුමක්ද?", listOf("${((10 + (v % 4) * 2) * (8 + (v % 3) * 2)) / 2} cm²", "${(10 + (v % 4) * 2) * (8 + (v % 3) * 2)} cm²", "40 cm²", "80 cm²"), 1, "රොම්බසයක වර්ගඵලය = 1/2 × විකර්ණ දෙකෙහි ගුණිතය වේ."),
          Quad("පාදයක දිග ${6 + (v % 5)} cm වූ සමචතුරස්‍රාකාර තහඩුවක මුළු වර්ගඵලය කොපමණද?", listOf("${(6 + (v % 5)) * (6 + (v % 5))} cm²", "${4 * (6 + (v % 5))} cm²", "${2 * (6 + (v % 5))} cm²", "36 cm²"), 1, "සමචතුරස්‍ර වර්ගඵලය = පාදය² = ${6 + (v % 5)} × ${6 + (v % 5)} = ${(6 + (v % 5)) * (6 + (v % 5))} cm².")
        )
        areaList[(slot - 8 + v).mod(areaList.size)]
      }
      in 15..21 -> "භාග (Fractions)" to run {
        val fracList = listOf(
          Quad("1/2 + ${1 + (v % 3)}/4 සුළු කළ විට ලැබෙන අගය කුමක්ද?", listOf("${2 + 1 + (v % 3)}/4", "3/4", "1/4", "5/4"), 1, "පොදු හරය 4 ගත් විට: 2/4 + ${1 + (v % 3)}/4 = ${2 + 1 + (v % 3)}/4 වේ."),
          Quad("3/4 - 1/${2 + (v % 2) * 2} සුළු කළ විට ලැබෙන සරලම භාගය කුමක්ද?", listOf(if ((v % 2) == 0) "1/4" else "2/4 (1/2)", "1/2", "3/8", "1/8"), 1, "පොදු හරය ගෙන අඩු කිරීමෙන් පිළිතුර ලැබේ."),
          Quad("(2/3) × (${3 + (v % 3)}/4) ගුණිතයේ අගය කුමක්ද?", listOf("${2 * (3 + (v % 3))}/12", "1/2", "3/4", "2/3"), 1, "හරය හරයෙන්ද අංශය අංශයෙන්ද ගුණ කර සුළු කරනු ලැබේ."),
          Quad("(3/5) ÷ (${1 + (v % 2)}/10) බෙදීමේ අගය කුමක්ද?", listOf("${(3 * 10) / (5 * (1 + (v % 2)))}", "6", "3", "5"), 1, "(3/5) × (10 / ${1 + (v % 2)}) = ${(3 * 10) / (5 * (1 + (v % 2)))} වේ."),
          Quad("මිශ්‍ර සංඛ්‍යාවක් වන 2 ${1 + (v % 2)}/3 විෂම භාගයක් බවට පත් කළ විට කුමක්ද?", listOf("${2 * 3 + 1 + (v % 2)}/3", "7/3", "5/3", "8/3"), 1, "(පූර්ණ සංඛ්‍යාව × හරය + අංශය) / හරය = (2 × 3 + ${1 + (v % 2)}) / 3 = ${2 * 3 + 1 + (v % 2)}/3 වේ."),
          Quad("පොතක පිටු 120 න් 2/3 ක් කියවූ පසු තව කියවීමට ඉතිරි පිටු ගණන කොපමණද?", listOf("පිටු 40", "පිටු 80", "පිටු 60", "පිටු 30"), 1, "කියවූ පිටු = 120 × (2/3) = 80. ඉතිරි පිටු = 120 - 80 = 40."),
          Quad("වැටුපෙන් 1/4 ක් ආහාර සඳහාද, 1/2 ක් නවාතැන් සඳහාද වියදම් කළ පසු ඉතිරි භාගය කොපමණද?", listOf("1/4", "1/2", "3/4", "1/8"), 1, "වියදම් කළ මුළු භාගය = 1/4 + 1/2 = 3/4. ඉතිරි භාගය = 1 - 3/4 = 1/4 වේ.")
        )
        fracList[(slot - 15 + v).mod(fracList.size)]
      }
      in 22..28 -> "ප්‍රතිශත සහ ලාභ/අලාභ" to run {
        val pctList = listOf(
          Quad("රු. ${500 + v * 100} කට ගත් භාණ්ඩයක් 20% ක ලාභයක් තබා විකිණූ විට විකුණුම් මිල කොපමණද?", listOf("රු. ${((500 + v * 100) * 120) / 100}", "රු. ${500 + v * 100 + 100}", "රු. 600", "රු. 700"), 1, "විකුණුම් මිල = ගැනුම් මිල × 120% = ${500 + v * 100} × 1.2 = රු. ${((500 + v * 100) * 120) / 100} වේ."),
          Quad("ලකුණු කළ මිල රු. ${1000 + v * 200} වූ ඇඳුමකට 10% ක වට්ටමක් දුන් විට ගෙවිය යුතු මුදල කුමක්ද?", listOf("රු. ${((1000 + v * 200) * 90) / 100}", "රු. ${1000 + v * 200 - 100}", "රු. 900", "රු. 1800"), 1, "වට්ටම = 10%. ගෙවිය යුතු මිල = ලකුණු කළ මිල × 90% = රු. ${((1000 + v * 200) * 90) / 100}."),
