          Quad("ත්‍රිකෝණයක පාදයක දිග 16 cm නම්, අනෙක් පාද දෙකේ මධ්‍ය ලක්ෂ්‍ය යා කරන රේඛා ඛණ්ඩයේ දිග කුමක්ද?", listOf("8 cm", "16 cm", "4 cm", "12 cm"), 1, "මධ්‍ය ලක්ෂ්‍ය ප්‍රමේයය අනුව: දිග = 16 / 2 = 8 cm වේ."),
          Quad("සියලු අභ්‍යන්තර කෝණ 90° වන අතර විකර්ණ දිගින් සමාන වන සමාන්තරාස්‍රය කුමක්ද?", listOf("සෘජුකෝණාස්‍රය (සහ සමචතුරස්‍රය)", "රොම්බසය", "සාමාන්‍ය සමාන්තරාස්‍රය", "ත්‍රපීසියම"), 1, "සෘජුකෝණාස්‍රයක කෝණ 90° වන අතර විකර්ණ දිගින් සමාන වේ."),
          Quad("චතුරස්‍රයක එක් සම්මුඛ පාද යුගලයක් පමණක් සමාන්තර වේ නම් එය කුමක්ද?", listOf("ත්‍රපීසියම (Trapezium)", "සමාන්තරාස්‍රය", "රොම්බසය", "සෘජුකෝණාස්‍රය"), 1, "එක් පාද යුගලයක් පමණක් සමාන්තර චතුරස්‍රය ත්‍රපීසියමයි.")
        )
        pList[(slot - 44 + v).mod(pList.size)]
      }
      else -> "සරල රේඛා ප්‍රස්ථාර (Straight Line Graphs)" to run {
        val m = 2 + (v % 4)
        val c = 3 + (v % 5)
        val graphList = listOf(
          Quad("y = ${m}x + $c සරල රේඛාවේ අනුක්‍රමණය (m) සහ y-අන්තඃඛණ්ඩය (c) පිළිවෙළින් කුමක්ද?", listOf("m = $m, c = $c", "m = $c, c = $m", "m = -$m, c = $c", "m = 1, c = 0"), 1, "y = mx + c සම්මත සමීකරණයේ x හි සංගුණකය අනුක්‍රමණය $m ද, නියත පදය y-අන්තඃඛණ්ඩය $c ද වේ."),
          Quad("(0, 0) සහ (${2 + (v % 2)}, ${2 * (2 + (v % 2))}) ලක්ෂ්‍ය හරහා යන සරල රේඛාවේ අනුක්‍රමණය කුමක්ද?", listOf("2", "1", "4", "1/2"), 1, "අනුක්‍රමණය m = (y₂ - y₁) / (x₂ - x₁) = (${2 * (2 + (v % 2))} - 0) / (${2 + (v % 2)} - 0) = 2 වේ."),
          Quad("x-අක්ෂයට සමාන්තරව (2, 5) ලක්ෂ්‍යය හරහා යන සරල රේඛාවේ සමීකරණය කුමක්ද?", listOf("y = 5", "x = 2", "y = 2", "x = 5"), 1, "x-අක්ෂයට සමාන්තර රේඛාවක y ඛණ්ඩාංකය නියත වේ: y = 5."),
          Quad("y-අක්ෂයට සමාන්තරව (4, -1) හරහා යන සරල රේඛාවේ සමීකරණය කුමක්ද?", listOf("x = 4", "y = -1", "x = -1", "y = 4"), 1, "y-අක්ෂයට සමාන්තර රේඛාවක සමීකරණය x = නියතයකි: x = 4."),
          Quad("y = 3x - 6 සරල රේඛාව x-අක්ෂය ඡේදනය කරන ලක්ෂ්‍යයේ ඛණ්ඩාංක මොනවාද?", listOf("(2, 0)", "(0, -6)", "(0, 2)", "(-2, 0)"), 1, "x-අක්ෂය ඡේදනයේදී y = 0 වේ: 0 = 3x - 6 => 3x = 6 => x = 2. එබැවින් (2, 0) වේ."),
          Quad("y = -2x + 4 සරල රේඛාවේ අනුක්‍රමණය සතු ලක්ෂණය කුමක්ද?", listOf("සෘණ අනුක්‍රමණයකි (වමේ සිට දකුණට පහළට බසී)", "ධන අනුක්‍රමණයකි", "ශුන්‍ය වේ", "අර්ථ දැක්විය නොහැක"), 1, "m = -2 සෘණ බැවින් රේඛාව දකුණට බසින ආනතියක් දරයි."),
          Quad("සමාන්තර සරල රේඛා දෙකක අනුක්‍රමණ (m₁ සහ m₂) අතර සම්බන්ධය කුමක්ද?", listOf("m₁ = m₂ (අනුක්‍රමණ සමාන වේ)", "m₁ × m₂ = -1", "m₁ + m₂ = 0", "සම්බන්ධයක් නැත"), 1, "සමාන්තර රේඛාවල බෑවුම (අනුක්‍රමණය) සමාන වේ."),
          Quad("එකිනෙකට ලම්භක සරල රේඛා දෙකක අනුක්‍රමණවල ගුණිතය කුමක්ද?", listOf("m₁ × m₂ = -1", "m₁ = m₂", "m₁ × m₂ = 1", "0"), 1, "ලම්භක රේඛා දෙකක අනුක්‍රමණ ගුණිතය -1 කි.")
        )
        graphList[(slot - 52 + v).mod(graphList.size)]
      }
    }

    return MockExamQuestion(
      id = qNum,
      questionText = "ආදර්ශ පත්‍රය ${String.format("%02d", paperIdx)} • ප්‍රශ්නය $qNum: ${quad.q}",
      options = quad.opts,
      correctOption = quad.c,
      explanation = quad.exp,
      topicName = topic
    )
  }

  // ==========================================================================
  // GRADE 10 - TERM 3 (Slots 1 to 60)
  // ==========================================================================
  private fun getTerm3Question(paperIdx: Int, qNum: Int, slot: Int): MockExamQuestion {
    val v = paperIdx - 1
    val (topic, quad) = when (slot) {
      in 1..7 -> "ම.පො.සා. සහ කු.පො.ගු. (HCF & LCM)" to run {
        val hcfList = listOf(
          Quad("6x²y සහ 9xy² යන වීජීය පද දෙකෙහි මහා පොදු සාධකය (ම.පො.සා.) කුමක්ද?", listOf("3xy", "18x²y²", "3x²y²", "6xy"), 1, "සංඛ්‍යාත්මක සාධකය 3 වන අතර අකුරුවල අවම බලය xy වේ: 3xy."),
          Quad("4a²b සහ 6ab² පද දෙකෙහි කුඩා පොදු ගුණාකාරය (කු.පො.ගු.) කුමක්ද?", listOf("12a²b²", "2ab", "24a³b³", "12ab"), 1, "සංඛ්‍යාත්මක කු.පො.ගු. 12 වන අතර අකුරුවල උපරිම බලය a²b² වේ: 12a²b²."),
          Quad("(x - 2)² සහ (x - 2)(x + 3) හි ම.පො.සා. කුමක්ද?", listOf("(x - 2)", "(x - 2)²(x + 3)", "(x + 3)", "1"), 1, "පොදු සාධකයේ අවම බලය (x - 2) වේ."),
          Quad("(x + 1) සහ (x - 1) ප්‍රකාශන දෙකෙහි කු.පො.ගු. කුමක්ද?", listOf("(x + 1)(x - 1) හෝ x² - 1", "1", "x² + 1", "2x"), 1, "පොදු සාධක නොමැති බැවින් කු.පො.ගු. යනු ඒවායේ ගුණිතයයි: (x + 1)(x - 1)."),
          Quad("12x සහ 18x² හි ම.පො.සා. කුමක්ද?", listOf("6x", "36x²", "6x²", "12x"), 1, "12 සහ 18 හි ම.පො.සා. 6 ද, x සහ x² හි ම.පො.සා. x ද වේ: 6x."),
          Quad("8ab සහ 12bc හි කු.පො.ගු. කුමක්ද?", listOf("24abc", "4b", "96ab²c", "24b"), 1, "8 සහ 12 හි කු.පො.ගු. 24 වන අතර අකුරු සංයෝජනය abc වේ: 24abc."),
          Quad("x² - 4 සහ (x - 2) හි ම.පො.සා. කුමක්ද?", listOf("(x - 2)", "(x + 2)", "(x² - 4)", "1"), 1, "x² - 4 = (x - 2)(x + 2) බැවින් පොදු සාධකය (x - 2) වේ.")
        )
        hcfList[(slot - 1 + v).mod(hcfList.size)]
      }
      in 8..15 -> "වීජීය භාග (Algebraic Fractions)" to run {
        val fracList = listOf(
          Quad("2/x + 3/x සුළු කළ විට ලැබෙන්නේ කුමක්ද?", listOf("5/x", "5/2x", "6/x²", "5/x²"), 1, "හරයන් සමාන බැවින් අංශයන් එකතු වේ: (2 + 3) / x = 5/x."),
          Quad("1/(2x) + 1/(3x) සුළු කළ විට සරලම භාගය කුමක්ද?", listOf("5/(6x)", "2/(5x)", "1/(6x)", "5/(6x²)"), 1, "පොදු හරය 6x වේ: (3 + 2) / 6x = 5/(6x)."),
          Quad("(x / 2) × (4 / x) ගුණිතයේ අගය කුමක්ද? (x ≠ 0)", listOf("2", "4x / 2x", "x / 2", "2x"), 1, "x ට x කැපී ගොස් 4/2 = 2 ලැබේ."),
          Quad("(2x / 3) ÷ (4x / 9) බෙදූ විට අගය කුමක්ද?", listOf("3/2 (1.5)", "2/3", "8x² / 27", "1"), 1, "(2x / 3) × (9 / 4x) = 18 / 12 = 3/2 වේ."),
          Quad("3/(x - 1) - 1/(x - 1) හි අගය කුමක්ද?", listOf("2/(x - 1)", "4/(x - 1)", "2", "2/(x - 1)²"), 1, "හරය සමාන බැවින් (3 - 1) / (x - 1) = 2/(x - 1) වේ."),
          Quad("(x² - 1) / (x - 1) සරල කළ විට කුමක්ද? (x ≠ 1)", listOf("x + 1", "x - 1", "1", "x"), 1, "(x - 1)(x + 1) / (x - 1) = x + 1 වේ."),
          Quad("a/b × b/c × c/a හි අගය කුමක්ද?", listOf("1", "abc", "0", "a²b²c²"), 1, "සියලු පද එකිනෙක කැපී ගොස් 1 ලැබේ."),
          Quad("1/x = 1/4 නම් x හි අගය කුමක්ද?", listOf("4", "1/4", "1", "16"), 1, "ප්‍රතිලෝම කිරීමෙන් x = 4 වේ.")
        )
        fracList[(slot - 8 + v).mod(fracList.size)]
      }
      in 16..23 -> "පයිතගරස් ප්‍රමේයය (Pythagoras Theorem)" to run {
        val a = 3 * (1 + (v % 3))
        val b = 4 * (1 + (v % 3))
        val c = 5 * (1 + (v % 3))
        val pythList = listOf(
          Quad("සෘජුකෝණී ත්‍රිකෝණයක ලම්භ පාද $a cm සහ $b cm නම් කර්ණයේ දිග කොපමණද?", listOf("$c cm", "${a + b} cm", "${c + 2} cm", "${a * b} cm"), 1, "c² = a² + b² = $a² + $b² = ${a*a + b*b} => c = $c cm."),
          Quad("කර්ණය 13 cm සහ එක් පාදයක් 5 cm වූ සෘජුකෝණී ත්‍රිකෝණයේ අනෙක් පාදයේ දිග කුමක්ද?", listOf("12 cm", "8 cm", "10 cm", "14 cm"), 1, "b² = 13² - 5² = 169 - 25 = 144 => b = 12 cm."),
