        val lociList = listOf(
          Quad("ස්ථාවර ලක්ෂ්‍යයක සිට නියත දුරකින් චලනය වන ලක්ෂ්‍යයක පථය කුමක්ද?", listOf("වෘත්තයකි (Circle)", "සරල රේඛාවකි", "පරාවලයකී", "ත්‍රිකෝණයකි"), 1, "කේන්ද්‍රයේ සිට නියත අරයකින් ගමන් කරන ලක්ෂ්‍ය පථය වෘත්තයකි."),
          Quad("දී ඇති ස්ථාවර ලක්ෂ්‍ය දෙකකට සමදුරින් චලනය වන ලක්ෂ්‍යයේ පථය කුමක්ද?", listOf("ලක්ෂ්‍ය දෙක යා කරන රේඛාවේ ලම්භ සමච්ඡේදකය", "වෘත්තයකි", "සමාන්තර රේඛාවකි", "කෝණ සමච්ඡේදකය"), 1, "ලක්ෂ්‍ය දෙකකට සමදුරින් පිහිටි ලක්ෂ්‍ය පථය ලම්භ සමච්ඡේදක රේඛාවයි."),
          Quad("ඡේදනය වන සරල රේඛා දෙකකට සමදුරින් චලනය වන ලක්ෂ්‍යයේ පථය කුමක්ද?", listOf("එම රේඛා අතර කෝණයේ සමච්ඡේදකය (Angle bisector)", "ලම්භකය", "වෘත්තය", "සමාන්තර රේඛාව"), 1, "රේඛා දෙකකට සමදුරින් පිහිටි ලක්ෂ්‍ය පථය කෝණ සමච්ඡේදක රේඛා යුගලයයි."),
          Quad("දී ඇති සරල රේඛාවකට නියත d දුරකින් චලනය වන ලක්ෂ්‍යයක පථය කුමක්ද?", listOf("එම රේඛාවට දෙපසින් d දුරින් පිහිටි සමාන්තර සරල රේඛා යුගලය", "වෘත්තයකි", "ලම්භකයකි", "තනි ලක්ෂ්‍යයකි"), 1, "රේඛාවක සිට නියත දුරින් පිහිටි පථය සමාන්තර රේඛා යුගලයයි."),
          Quad("කවකටුව හා පරිමාණයක් පමණක් භාවිතයෙන් 60° ක කෝණයක් නිර්මාණය කිරීමට අඳිනු ලබන්නේ කුමක්ද?", listOf("සමපාද ත්‍රිකෝණයක ශීර්ෂ කෝණ නිර්මාණය", "සෘජුකෝණය සමච්ඡේදනය", "වෘත්තයක්", "චතුරස්‍රයක්"), 1, "සමාන අරයෙන් චාප කැපීමෙන් සමපාද ත්‍රිකෝණයක 60° කෝණය ලැබේ."),
          Quad("90° ක සෘජුකෝණයක් කෝණ සමච්ඡේදනය කළ විට ලැබෙන කෝණයේ විශාලත්වය කුමක්ද?", listOf("45°", "30°", "60°", "40°"), 1, "90° / 2 = 45° වේ."),
          Quad("රේඛා ඛණ්ඩයක මධ්‍ය ලක්ෂ්‍යය සෙවීමට යොදාගන්නා නිර්මාණය කුමක්ද?", listOf("ලම්භ සමච්ඡේදක නිර්මාණය", "කෝණ සමච්ඡේදනය", "සමාන්තර රේඛා නිර්මාණය", "ස්පර්ශක නිර්මාණය"), 1, "ලම්භ සමච්ඡේදකය රේඛාව හරියටම මැදින් දෙකට බෙදයි."),
          Quad("120° ක කෝණයක් සමච්ඡේදනය කළ විට ලැබෙන කෝණය කුමක්ද?", listOf("60°", "90°", "45°", "30°"), 1, "120° / 2 = 60° වේ.")
        )
        lociList[(slot - 40 + v).mod(lociList.size)]
      }
      in 48..54 -> "තල රූපවල පරිමිතිය හා වර්ගඵල මිශ්‍ර ගැටලු" to run {
        val mixedList = listOf(
          Quad("පැත්තක දිග 14 cm වූ සමචතුරස්‍රයකින් කපා ඉවත් කළ හැකි විශාලතම වෘත්තයේ වර්ගඵලය කුමක්ද? (π = 22/7)", listOf("154 cm²", "196 cm²", "44 cm²", "88 cm²"), 1, "වෘත්තයේ විෂ්කම්භය 14 cm => අරය 7 cm. වර්ගඵලය = (22/7) × 7² = 154 cm² වේ."),
          Quad("දිග 20 m සහ පළල 15 m වූ සෘජුකෝණාස්‍රාකාර ඉඩමක වර්ගඵලය කොපමණද?", listOf("300 m²", "70 m²", "150 m²", "350 m²"), 1, "වර්ගඵලය = 20 × 15 = 300 m² වේ."),
          Quad("පරිමිතිය 36 cm වූ සමචතුරස්‍රයක වර්ගඵලය කොපමණද?", listOf("81 cm²", "36 cm²", "72 cm²", "18 cm²"), 1, "පාදය = 36 / 4 = 9 cm. වර්ගඵලය = 9 × 9 = 81 cm² වේ."),
          Quad("වර්ගඵලය 64 cm² වූ සමචතුරස්‍රයක පරිමිතිය කුමක්ද?", listOf("32 cm", "16 cm", "64 cm", "24 cm"), 1, "පාදය = √64 = 8 cm. පරිමිතිය = 8 × 4 = 32 cm."),
          Quad("සෘජුකෝණාස්‍රයක දිග පළල මෙන් දෙගුණයකි. පළල 5 cm නම් එහි වර්ගඵලය කුමක්ද?", listOf("50 cm²", "25 cm²", "100 cm²", "30 cm²"), 1, "දිග = 10 cm, පළල = 5 cm. වර්ගඵලය = 10 × 5 = 50 cm² වේ."),
          Quad("අරය 7 cm වූ කේන්ද්‍රික කෝණය 180° වූ අර්ධ වෘත්තයක වර්ගඵලය කුමක්ද?", listOf("77 cm²", "154 cm²", "44 cm²", "38.5 cm²"), 1, "අර්ධ වෘත්ත වර්ගඵලය = 1/2 × πr² = 1/2 × 154 = 77 cm² වේ."),
          Quad("ආධාරකය 10 cm සහ වර්ගඵලය 40 cm² වූ ත්‍රිකෝණයේ ලම්භ උස කොපමණද?", listOf("8 cm", "4 cm", "10 cm", "16 cm"), 1, "1/2 × 10 × h = 40 => 5h = 40 => h = 8 cm වේ.")
        )
        mixedList[(slot - 48 + v).mod(mixedList.size)]
      }
      else -> "විභාග ඉලක්කගත මිශ්‍ර ගණිත ගැටලු" to run {
        val final10List = listOf(
          Quad("2, 5, 8, 11, ... සංඛ්‍යා රටාවේ 10 වන පදය කුමක්ද?", listOf("29", "30", "28", "32"), 1, "T_n = a + (n - 1)d = 2 + (10 - 1)3 = 2 + 27 = 29 වේ."),
          Quad("3x - 4 > 5 අසමානතාවය තෘප්ත කරන x හි කුඩාම නිඛිලමය අගය කුමක්ද?", listOf("4", "3", "5", "2"), 1, "3x > 9 => x > 3. කුඩාම නිඛිලය 4 වේ."),
          Quad("මිල රු. 1200 ක් වූ භාණ්ඩයකට 15% ක වට්ටමක් දුන් පසු මිල කුමක්ද?", listOf("රු. 1020", "රු. 1000", "රු. 1050", "රු. 1185"), 1, "වට්ටම = 180. ගෙවිය යුතු මුදල = 1200 - 180 = රු. 1020."),
          Quad("ත්‍රිකෝණයක කෝණ 1 : 2 : 3 අනුපාතයට බෙදී ඇත්නම් එහි විශාලතම කෝණය කුමක්ද?", listOf("90°", "60°", "120°", "100°"), 1, "මුළු කොටස් = 6. 180° / 6 = 30°. විශාලතම කෝණය = 30° × 3 = 90°."),
          Quad("x = 3 වන විට 2x² - 5 හි අගය කොපමණද?", listOf("13", "11", "31", "18"), 1, "2(3)² - 5 = 2(9) - 5 = 18 - 5 = 13 වේ."),
          Quad("පැයට කිලෝමීටර 72 ක වේගයෙන් (72 km/h) ධාවනය වන දුම්රියක වේගය තත්පරයට මීටරවලින් (m/s) කොපමණද?", listOf("20 m/s", "15 m/s", "25 m/s", "72 m/s"), 1, "72 × (5 / 18) = 20 m/s වේ.")
        )
        final10List[(slot - 55 + v).mod(final10List.size)]
      }
    }

    return MockExamQuestion(
      id = qNum,
      questionText = "ආදර්ශ පත්‍රය ${String.format("%02d", paperIdx)} • ප්‍රශ්නය $qNum: ${quad.q}",
      options = quad.opts,
      correctOption = quad.c,
      explanation = quad.exp,
      topicName = topic
    )
  }

  private data class Quad(
    val q: String,
    val opts: List<String>,
    val c: Int,
    val exp: String
  )
}
